window.MG_LAZY_DATA["data/lazy/owner-courses/d201-f19202140cc225b7.json"]={sha256:"f19202140cc225b74042c66bf6160c45481b9fdc786533fde72859633765beda",value:{"id":"d201","title":"EMI早期電腦斷層掃描器工程","titleEn":"EMI Early Computed Tomography Scanner Engineering","category":"biomedical","kind":"course","summary":"從 EMI 早期設備史出發，以數位假體拆解投影、重建與影像品質。","summaryEn":"Start with early EMI equipment history and use digital phantoms to study projections, reconstruction and image quality.","scope":"十二步限於設備物理、數位假體與品質追溯。歷史設備與現代 QA 來源分別標示，不推定規格相同。不操作輻射設備、不使用病人資料、不提供診斷、治療或臨床掃描設定；不是醫療設備製造或驗收 SOP。","scopeEn":"Twelve tasks cover equipment physics, digital phantoms and quality traceability. Historical equipment and modern QA sources are distinguished without assuming identical specifications. No radiation equipment, patient data, diagnosis, treatment or clinical scan settings are used; this is not a medical-device manufacturing or acceptance SOP.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-science-emi-object","v6-science-hounsfield-lecture","v6-science-ct-quality","v10-other-vendor-d201"],"depth":4,"diagram":{"type":"biomedical","labels":["數位假體","投影","資料索引","重建","品質比較"],"labelsEn":["Digital phantom","Projections","Data indexing","Reconstruction","Quality comparison"],"original":true,"notToScale":true},"stages":[{"id":"d201-stage01","order":1,"title":"證據、假體與投影","titleEn":"Evidence, phantoms and projections","description":"用已知數位矩陣建立可追溯的反問題。","descriptionEn":"Build a traceable inverse problem from a known digital matrix.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d201-v6-01","order":1,"sequence":1,"prerequisiteIds":[],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-emi-object","v6-science-hounsfield-lecture","v6-science-ct-quality"],"title":"建立早期 CT 的證據與功能邊界","titleEn":"Establish evidence and function boundaries for early CT","objective":"區分歷史設備事實、重建原理與現代品質方法。","objectiveEn":"Distinguish historical equipment facts, reconstruction principles and modern quality methods.","instruction":"排列多角度衰減投影、重建、影像三張卡；將 EMI 典藏紀錄與現代品質指南分欄。","instructionEn":"Order multi-angle attenuation projections, reconstruction and image cards; separate the EMI collection record from modern quality guidance.","observation":"歷史設備與現代品質原理可以互相說明，但不能假定規格完全相同。","observationEn":"Historical equipment and modern quality principles can inform each other without implying identical specifications.","failure":"把現代指南中的性能值套回 1971 年設備，會造成時代錯置。","failureEn":"Assigning modern performance values to the 1971 instrument creates an anachronism.","check":"每項主張都有歷史或原理標籤，並附相對應來源。","checkEn":"Label every claim as historical or conceptual and attach the appropriate source.","knowledge":[{"id":"d201-v6-01-k1","title":"工程原理","titleEn":"Engineering principle","text":"CT 從多方向的衰減資訊推估物體內部的空間分布。","textEn":"CT estimates internal spatial distributions from attenuation information collected in multiple directions."},{"id":"d201-v6-01-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課只使用數位假體，不操作 X 光設備或解讀病人影像。","textEn":"This course uses digital phantoms only, without operating X-ray equipment or interpreting patient images."}],"quiz":{"question":"哪條資訊鏈最符合 CT 的基本原理？","questionEn":"Which information chain best describes CT?","options":["多角度投影→計算重建→影像","單張外觀照片→直接得知所有內部細節","先指定診斷→再修改投影符合答案"],"optionsEn":["Multi-angle projections → computational reconstruction → image","One external photograph → complete internal detail","Assign diagnosis → alter projections to match it"],"answer":0,"explanation":"CT 從多方向的衰減資訊推估物體內部的空間分布。 本課只使用數位假體，不操作 X 光設備或解讀病人影像。","explanationEn":"CT estimates internal spatial distributions from attenuation information collected in multiple directions. This course uses digital phantoms only, without operating X-ray equipment or interpreting patient images."}},{"id":"d201-v6-02","order":2,"sequence":2,"prerequisiteIds":["d201-v6-01"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hounsfield-lecture","v6-science-ct-quality"],"title":"建立帶座標的數位假體","titleEn":"Build a coordinate-labelled digital phantom","objective":"使像素位置、數值與已知真值可追溯。","objectiveEn":"Make pixel location, value and known ground truth traceable.","instruction":"畫 2×2 假體，第一列 1、2，第二列 3、4；標列、欄與任意衰減單位。","instructionEn":"Draw a 2×2 phantom with rows [1,2] and [3,4]; label rows, columns and arbitrary attenuation units.","observation":"四個像素的座標與數值具有確定對應。","observationEn":"Each of the four pixel coordinates has a defined value.","failure":"轉置陣列但不改座標標示，會讓方向判讀錯誤。","failureEn":"Transposing the array without relabelling coordinates causes orientation errors.","check":"請另一位學徒按座標重建同一矩陣，核對四個位置。","checkEn":"Ask another learner to reproduce the matrix from coordinates and check all four positions.","knowledge":[{"id":"d201-v6-02-k1","title":"工程原理","titleEn":"Engineering principle","text":"數位假體提供已知真值，便於測試演算法而不涉及人體。","textEn":"A digital phantom provides known ground truth for testing algorithms without human subjects."},{"id":"d201-v6-02-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"任意單位不是人體組織的 CT 值，也沒有診斷意義。","textEn":"Arbitrary units are not tissue CT values and have no diagnostic meaning."}],"quiz":{"question":"為什麼假體必須標座標？","questionEn":"Why must the phantom have coordinate labels?","options":["使所有像素自動變得相同","讓位置與數值對應可以重現","讓任意數字成為病人測量值"],"optionsEn":["To make all pixels identical automatically","To reproduce the mapping between location and value","To turn arbitrary numbers into patient measurements"],"answer":1,"explanation":"數位假體提供已知真值，便於測試演算法而不涉及人體。 任意單位不是人體組織的 CT 值，也沒有診斷意義。","explanationEn":"A digital phantom provides known ground truth for testing algorithms without human subjects. Arbitrary units are not tissue CT values and have no diagnostic meaning."}},{"id":"d201-v6-03","order":3,"sequence":3,"prerequisiteIds":["d201-v6-02"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hounsfield-lecture"],"title":"計算兩方向的線積分近似","titleEn":"Calculate two-direction line-sum approximations","objective":"理解投影如何壓縮沿路徑的資訊。","objectiveEn":"Understand how projections combine information along paths.","instruction":"對前步 2×2 假體算列和 3、7 與欄和 4、6，保留其方向標籤。","instructionEn":"Calculate row sums 3,7 and column sums 4,6 for the previous 2×2 phantom, retaining direction labels.","observation":"每個和只保留沿一條路徑的總貢獻。","observationEn":"Each sum retains only the total contribution along one path.","failure":"把某條投影和當成單一像素值，會混淆量測與未知量。","failureEn":"Treating a projection sum as one pixel confuses measurements with unknowns.","check":"確認兩方向的總和都為 10，並註明這是簡化線和模型。","checkEn":"Confirm both directions total 10 and label this as a simplified line-sum model.","knowledge":[{"id":"d201-v6-03-k1","title":"工程原理","titleEn":"Engineering principle","text":"理想化 CT 投影可用沿射線的衰減積分表示。","textEn":"Idealized CT projections can be represented by attenuation integrals along rays."},{"id":"d201-v6-03-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本例略去射束能譜、散射與探測器效應，只教幾何與守恆。","textEn":"This example omits spectra, scatter and detector effects to teach geometry and conservation."}],"quiz":{"question":"第一列的投影和是多少？","questionEn":"What is the first row’s projection sum?","options":["1","10","3"],"optionsEn":["1","10","3"],"answer":2,"explanation":"理想化 CT 投影可用沿射線的衰減積分表示。 本例略去射束能譜、散射與探測器效應，只教幾何與守恆。","explanationEn":"Idealized CT projections can be represented by attenuation integrals along rays. This example omits spectra, scatter and detector effects to teach geometry and conservation."}},{"id":"d201-v6-04","order":4,"sequence":4,"prerequisiteIds":["d201-v6-03"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hounsfield-lecture"],"title":"辨識有限角度的不唯一性","titleEn":"Identify ambiguity from limited directions","objective":"說明少量投影不能唯一決定內部矩陣。","objectiveEn":"Explain why a few projections need not uniquely determine an internal matrix.","instruction":"比較矩陣 [1,2;3,4] 與 [2,1;2,5] 的列和及欄和。","instructionEn":"Compare row and column sums of matrices [1,2;3,4] and [2,1;2,5].","observation":"兩矩陣都有列和 3、7 與欄和 4、6，但內部數值不同。","observationEn":"Both have row sums 3,7 and column sums 4,6 despite different internal values.","failure":"只匹配兩方向投影就宣稱真值唯一，會掩蓋資料不足。","failureEn":"Claiming unique truth from two matching directions hides insufficient data.","check":"列出另一方向或額外限制可能補充的資訊，不憑空假設真值。","checkEn":"List information another direction or constraint could add without assuming the true answer.","knowledge":[{"id":"d201-v6-04-k1","title":"工程原理","titleEn":"Engineering principle","text":"反問題可能有多個符合少量量測的解。","textEn":"An inverse problem can have multiple solutions consistent with limited measurements."},{"id":"d201-v6-04-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"資料一致性是必要檢查，但不自動等於唯一或正確重建。","textEn":"Data consistency is necessary but does not automatically imply a unique or correct reconstruction."}],"quiz":{"question":"相同兩方向投影可以證明什麼？","questionEn":"What do equal projections in two directions establish?","options":["在這些量測下相容，但不保證內部唯一","每個內部像素必定相同","多角度量測毫無價值"],"optionsEn":["Consistency with those measurements, without guaranteeing a unique interior","Every internal pixel must be identical","Additional angles have no value"],"answer":0,"explanation":"反問題可能有多個符合少量量測的解。 資料一致性是必要檢查，但不自動等於唯一或正確重建。","explanationEn":"An inverse problem can have multiple solutions consistent with limited measurements. Data consistency is necessary but does not automatically imply a unique or correct reconstruction."}}]},{"id":"d201-stage02","order":2,"title":"資料鏈與重建","titleEn":"Data chain and reconstruction","description":"比較正規化、角度索引、反投影與前向檢查。","descriptionEn":"Compare normalization, angle indexing, backprojection and forward checks.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d201-v6-05","order":1,"sequence":5,"prerequisiteIds":["d201-v6-04"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hounsfield-lecture","v6-science-ct-quality"],"title":"區分原始訊號與正規化資料","titleEn":"Separate raw signals from normalized data","objective":"理解參考訊號與探測器偏差的角色。","objectiveEn":"Understand reference signals and detector bias.","instruction":"製作兩個虛構探測器卡，寫相同物體訊號但不同空白參考；標示需要校正的比較。","instructionEn":"Make two fictional detector cards with equal object signals but different blank references; mark the comparison needing correction.","observation":"原始數值相同不一定代表相同衰減比例。","observationEn":"Equal raw values do not necessarily represent equal attenuation ratios.","failure":"忽略參考值漂移，可能把儀器差異誤認為物體差異。","failureEn":"Ignoring reference drift can mistake instrumental differences for object differences.","check":"在資料表保留原始值、參考值、校正版本三欄。","checkEn":"Retain raw value, reference value and calibration version in separate columns.","knowledge":[{"id":"d201-v6-05-k1","title":"工程原理","titleEn":"Engineering principle","text":"量測需相對適當參考解讀，探測器偏差會傳到重建結果。","textEn":"Measurements require suitable references, and detector bias propagates into reconstruction."},{"id":"d201-v6-05-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"本課僅分類校正資料，不提供醫療設備現場校正操作。","textEn":"This task classifies calibration information without instructing onsite medical-equipment calibration."}],"quiz":{"question":"相同原始讀值、不同參考值時，應先做什麼？","questionEn":"With equal raw readings but different references, what comes first?","options":["直接宣稱兩個衰減量完全相同","審查正規化及參考一致性","刪除參考值以方便比較"],"optionsEn":["Declare the attenuation values identical","Review normalization and reference consistency","Delete references to simplify comparison"],"answer":1,"explanation":"量測需相對適當參考解讀，探測器偏差會傳到重建結果。 本課僅分類校正資料，不提供醫療設備現場校正操作。","explanationEn":"Measurements require suitable references, and detector bias propagates into reconstruction. This task classifies calibration information without instructing onsite medical-equipment calibration."}},{"id":"d201-v6-06","order":2,"sequence":6,"prerequisiteIds":["d201-v6-05"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hounsfield-lecture"],"title":"組織投影角度索引","titleEn":"Organize projection-angle indexing","objective":"保持角度、探測器位置與量測值同步。","objectiveEn":"Keep angle, detector position and measurement value synchronized.","instruction":"以三個假設角度與兩個探測器位置製作六格資料表，給每格唯一索引。","instructionEn":"Make a six-cell table for three assumed angles and two detector positions, assigning a unique index to each cell.","observation":"重排角度列時，對應數值必須一起移動。","observationEn":"Reordering angle rows requires moving the corresponding values with them.","failure":"只排序角度標籤而不移動數值，會造成錯誤幾何配對。","failureEn":"Sorting angle labels alone creates incorrect geometry–value pairings.","check":"隨機挑一格，能追溯其角度、位置與來源是假設還是引用。","checkEn":"Trace one selected cell to its angle, position and hypothetical or cited origin.","knowledge":[{"id":"d201-v6-06-k1","title":"工程原理","titleEn":"Engineering principle","text":"投影集合的幾何索引是重建輸入的一部分。","textEn":"Geometric indexing is part of the reconstruction input."},{"id":"d201-v6-06-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"這是自建小型資料表，不代表課程提供真實掃描器量測資料。","textEn":"This is a learner-built small table, not a supplied real-scanner dataset."}],"quiz":{"question":"排序投影時哪些資料必須一起移動？","questionEn":"What must move together when projections are sorted?","options":["只有角度文字","只有表格顏色","角度、位置與其對應數值"],"optionsEn":["Angle text alone","Table colours alone","Angle, position and associated value"],"answer":2,"explanation":"投影集合的幾何索引是重建輸入的一部分。 這是自建小型資料表，不代表課程提供真實掃描器量測資料。","explanationEn":"Geometric indexing is part of the reconstruction input. This is a learner-built small table, not a supplied real-scanner dataset."}},{"id":"d201-v6-07","order":3,"sequence":7,"prerequisiteIds":["d201-v6-06"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hounsfield-lecture","v6-science-ct-quality"],"title":"觀察簡單反投影的模糊","titleEn":"Observe blur in simple backprojection","objective":"理解把投影展回路徑不會立即恢復真值。","objectiveEn":"Understand why spreading projections back along paths does not immediately recover ground truth.","instruction":"把列和與欄和以半透明色帶展回 2×2 格線；與原假體逐格比較。","instructionEn":"Spread row and column sums back onto a 2×2 grid as translucent bands, then compare with the original phantom.","observation":"不同路徑的貢獻疊加，但細節不必等於原矩陣。","observationEn":"Contributions from different paths overlap without necessarily reproducing the original matrix.","failure":"把較亮的疊加圖直接稱為準確重建，會忽略模糊與正規化。","failureEn":"Calling a brighter overlay accurate reconstruction ignores blur and normalization.","check":"列出至少兩格差異，明確標為未濾波概念反投影。","checkEn":"List at least two cell differences and label the result conceptual unfiltered backprojection.","knowledge":[{"id":"d201-v6-07-k1","title":"工程原理","titleEn":"Engineering principle","text":"反投影把投影資訊分配回空間，仍需適當重建方法控制模糊。","textEn":"Backprojection redistributes projection information into space; suitable reconstruction methods are still needed to manage blur."},{"id":"d201-v6-07-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"少量角度的手繪示例不能用來評價臨床影像性能。","textEn":"A few-angle sketch cannot assess clinical image performance."}],"quiz":{"question":"反投影疊加後應先檢查什麼？","questionEn":"What should be checked after backprojection overlap?","options":["與已知假體的差異及所用方法限制","影像顏色是否好看","是否可直接作診斷"],"optionsEn":["Differences from known ground truth and method limitations","Whether the colours are attractive","Whether it can immediately support diagnosis"],"answer":0,"explanation":"反投影把投影資訊分配回空間，仍需適當重建方法控制模糊。 少量角度的手繪示例不能用來評價臨床影像性能。","explanationEn":"Backprojection redistributes projection information into space; suitable reconstruction methods are still needed to manage blur. A few-angle sketch cannot assess clinical image performance."}},{"id":"d201-v6-08","order":4,"sequence":8,"prerequisiteIds":["d201-v6-07"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-hounsfield-lecture"],"title":"用前向投影檢查候選重建","titleEn":"Check a candidate reconstruction by forward projection","objective":"將候選影像重新投影以檢查資料一致性。","objectiveEn":"Reproject a candidate image to check measurement consistency.","instruction":"對候選矩陣 [1,1;3,4] 算列和與欄和，與目標 3、7 與 4、6 比較。","instructionEn":"Compute row and column sums for candidate [1,1;3,4] and compare with targets 3,7 and 4,6.","observation":"第一列與第二欄各少 1，顯示候選未符合全部資料。","observationEn":"The first row and second column are each short by 1, so the candidate does not fit all data.","failure":"只比較總亮度可能漏掉哪條路徑不一致。","failureEn":"Comparing total brightness alone can miss which path is inconsistent.","check":"逐路徑列殘差並保留正負號，不擅自更改目標資料。","checkEn":"List signed residuals for each path without changing the target data.","knowledge":[{"id":"d201-v6-08-k1","title":"工程原理","titleEn":"Engineering principle","text":"前向模型把候選解轉回量測空間，便於比較殘差。","textEn":"A forward model maps a candidate solution back into measurement space for residual comparison."},{"id":"d201-v6-08-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"殘差為零仍受有限角度的不唯一性限制。","textEn":"Zero residual still does not resolve ambiguity from limited angles."}],"quiz":{"question":"示例候選哪裡不符合目標？","questionEn":"Where does the candidate fail to match the target?","options":["每條路徑都完全符合","第一列與第二欄各少 1","只有顏色不同，數值都相同"],"optionsEn":["Every path matches exactly","The first row and second column are each short by 1","Only colours differ; all values agree"],"answer":1,"explanation":"前向模型把候選解轉回量測空間，便於比較殘差。 殘差為零仍受有限角度的不唯一性限制。","explanationEn":"A forward model maps a candidate solution back into measurement space for residual comparison. Zero residual still does not resolve ambiguity from limited angles."}}]},{"id":"d201-stage03","order":3,"title":"品質特徵與驗證報告","titleEn":"Quality characteristics and verification","description":"分別審視偏差、雜訊、細節與可重現性。","descriptionEn":"Review bias, noise, detail and reproducibility separately.","route":"依學習相依關係閱讀；這四步是公開原理的概念任務，不是現場施工、操作或量產程序。","routeEn":"Follow the learning dependencies. These four tasks explore public principles; they are not field, operating or production procedures.","steps":[{"id":"d201-v6-09","order":1,"sequence":9,"prerequisiteIds":["d201-v6-08"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-ct-quality"],"title":"比較均勻區的偏差與雜訊","titleEn":"Compare bias and noise in a uniform region","objective":"區分整體偏移與數值分散。","objectiveEn":"Distinguish overall offset from spread.","instruction":"以已知示例真值 10，比較區域 A=[10,10,10] 與 B=[9,10,11]，再比較 C=[12,12,12]。","instructionEn":"With example truth 10, compare regions A=[10,10,10], B=[9,10,11] and C=[12,12,12].","observation":"B 有分散但平均為 10；C 一致但有偏差。","observationEn":"B has spread with mean 10; C is consistent but biased.","failure":"把低雜訊直接當作準確，會忽略系統性偏移。","failureEn":"Treating low noise as accuracy ignores systematic bias.","check":"分開寫平均差與數值分散，全部標任意教學單位。","checkEn":"Report mean error and spread separately, using arbitrary teaching units.","knowledge":[{"id":"d201-v6-09-k1","title":"工程原理","titleEn":"Engineering principle","text":"準確度、均勻性與雜訊描述不同品質特徵。","textEn":"Accuracy, uniformity and noise describe different quality characteristics."},{"id":"d201-v6-09-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"示例不含人體 CT 值或臨床合格門檻。","textEn":"The example contains no tissue CT values or clinical acceptance thresholds."}],"quiz":{"question":"哪個區域示範一致但有偏差？","questionEn":"Which region is consistent but biased?","options":["A=[10,10,10]","只要一致就不可能有偏差","C=[12,12,12]"],"optionsEn":["A=[10,10,10]","Consistency makes bias impossible","C=[12,12,12]"],"answer":2,"explanation":"準確度、均勻性與雜訊描述不同品質特徵。 示例不含人體 CT 值或臨床合格門檻。","explanationEn":"Accuracy, uniformity and noise describe different quality characteristics. The example contains no tissue CT values or clinical acceptance thresholds."}},{"id":"d201-v6-10","order":2,"sequence":10,"prerequisiteIds":["d201-v6-09"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-ct-quality"],"title":"辨識解析度與平滑的取捨","titleEn":"Identify the resolution–smoothing trade-off","objective":"說明降低波動可能同時抹去細節。","objectiveEn":"Explain how reducing variation can also erase detail.","instruction":"畫一條含單格窄峰的數位剖面，與三格移動平均後的剖面比較峰寬與峰高。","instructionEn":"Draw a digital profile with a one-cell narrow peak and compare peak width and height after a three-cell moving average.","observation":"平滑可能降低局部波動，也使窄峰展寬。","observationEn":"Smoothing can reduce local variation while broadening a narrow peak.","failure":"只以平滑外觀評分，會忽略小特徵辨識能力。","failureEn":"Scoring only smooth appearance ignores small-feature visibility.","check":"同時記錄波動改變與峰形改變，說明選用方法的目的。","checkEn":"Record both variation and peak-shape changes and explain the method’s purpose.","knowledge":[{"id":"d201-v6-10-k1","title":"工程原理","titleEn":"Engineering principle","text":"處理方法可以在雜訊與空間細節之間產生取捨。","textEn":"Processing methods can create a trade-off between noise and spatial detail."},{"id":"d201-v6-10-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"這是訊號處理練習，不建議病人掃描參數或影像診斷設定。","textEn":"This is signal-processing practice, not advice on patient scanning or diagnostic settings."}],"quiz":{"question":"平滑後圖更平順能證明什麼？","questionEn":"What does a smoother result establish?","options":["波動改變了，仍需檢查細節損失","所有影像品質都一定提高","可忽略解析度評估"],"optionsEn":["Variation changed; detail loss still needs checking","Every aspect of image quality improved","Resolution assessment is unnecessary"],"answer":0,"explanation":"處理方法可以在雜訊與空間細節之間產生取捨。 這是訊號處理練習，不建議病人掃描參數或影像診斷設定。","explanationEn":"Processing methods can create a trade-off between noise and spatial detail. This is signal-processing practice, not advice on patient scanning or diagnostic settings."}},{"id":"d201-v6-11","order":3,"sequence":11,"prerequisiteIds":["d201-v6-10"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-ct-quality"],"title":"把假體異常連回資料鏈","titleEn":"Trace phantom anomalies through the data chain","objective":"用可測假說區分物體、探測器與重建問題。","objectiveEn":"Separate object, detector and reconstruction issues using testable hypotheses.","instruction":"製作虛構案例：同一資料用兩個重建版本得到不同條紋；列出版本、校正與角度索引檢查。","instructionEn":"Create a fictional case where one dataset produces different streaks with two reconstruction versions; list version, calibration and angle-index checks.","observation":"資料相同而處理結果不同，應先審查處理鏈差異。","observationEn":"When identical data produce different outputs, processing-chain differences deserve initial review.","failure":"看到條紋就宣告病理異常，會越過設備品質課程的用途。","failureEn":"Declaring pathology from streaks exceeds the purpose of an equipment-quality lesson.","check":"每個假說附可重現比較，不對病人作任何結論。","checkEn":"Attach a reproducible comparison to each hypothesis and make no patient conclusions.","knowledge":[{"id":"d201-v6-11-k1","title":"工程原理","titleEn":"Engineering principle","text":"品質調查需要控制變因，才能把差異連回資料鏈。","textEn":"Quality investigation needs controlled variables to link differences to the data chain."},{"id":"d201-v6-11-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"此處所有案例為虛構數位假體，不是臨床判讀。","textEn":"Every case here is a fictional digital phantom, not clinical interpretation."}],"quiz":{"question":"同資料但不同重建版本出現差異時，首先應保留什麼？","questionEn":"With one dataset and different reconstruction outputs, what should be retained first?","options":["只保留較漂亮的圖","輸入資料與軟體版本的可追溯紀錄","任意修改資料直到兩圖相同"],"optionsEn":["Only the more attractive image","Traceable records of input data and software versions","Arbitrarily alter data until the images agree"],"answer":1,"explanation":"品質調查需要控制變因，才能把差異連回資料鏈。 此處所有案例為虛構數位假體，不是臨床判讀。","explanationEn":"Quality investigation needs controlled variables to link differences to the data chain. Every case here is a fictional digital phantom, not clinical interpretation."}},{"id":"d201-v6-12","order":4,"sequence":12,"prerequisiteIds":["d201-v6-11"],"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-science-emi-object","v6-science-hounsfield-lecture","v6-science-ct-quality"],"title":"完成無輻射的重建品質報告","titleEn":"Complete a radiation-free reconstruction quality report","objective":"交付可重現、有限度的數位假體驗證。","objectiveEn":"Deliver reproducible, bounded digital-phantom verification.","instruction":"整理假體矩陣、投影索引、候選殘差、偏差雜訊比較與方法版本，附來源和限制。","instructionEn":"Compile the phantom matrix, projection indices, candidate residuals, bias/noise comparison and method version, with sources and limitations.","observation":"已知真值、輸入與方法同時保存，才容易獨立重現。","observationEn":"Independent reproduction requires preserved ground truth, inputs and methods together.","failure":"把概念測試通過寫成醫療設備合格，會誇大驗證範圍。","failureEn":"Calling a passed concept test medical-device approval exaggerates verification scope.","check":"讓另一位學徒重算一條投影；報告明言沒有真實掃描、診斷或治療。","checkEn":"Have another learner recalculate one projection; state that no real scan, diagnosis or treatment occurred.","knowledge":[{"id":"d201-v6-12-k1","title":"工程原理","titleEn":"Engineering principle","text":"可重現報告應保留資料來源、方法、版本與適用邊界。","textEn":"A reproducible report preserves data origin, method, version and applicability boundaries."},{"id":"d201-v6-12-k2","title":"驗證與適用界限","titleEn":"Verification and limits","text":"完成本課只表示掌握影像物理的概念證據，不構成臨床能力認證。","textEn":"Completion demonstrates conceptual evidence in imaging physics, not certification of clinical competence."}],"quiz":{"question":"哪份報告的結論符合證據？","questionEn":"Which report conclusion matches the evidence?","options":["所有 CT 設備均已通過驗收","可直接替代醫療專業判讀","此數位假體在指定模型下通過已列檢查"],"optionsEn":["All CT devices have passed acceptance","It can replace professional clinical interpretation","This digital phantom passed the listed checks under the stated model"],"answer":2,"explanation":"可重現報告應保留資料來源、方法、版本與適用邊界。 完成本課只表示掌握影像物理的概念證據，不構成臨床能力認證。","explanationEn":"A reproducible report preserves data origin, method, version and applicability boundaries. Completion demonstrates conceptual evidence in imaging physics, not certification of clinical competence."}}]}],"status":"guided","languageCoverage":["zh-TW","en"],"curriculumVersion":6,"stepCount":12,"estimatedMinutes":240}};
